<js>
const loadLen=Number(java.get("文字长度"))||50;
function aWeb(u){java.log('正文WebView');
try{return java.webView(null,u,String.raw`(function(){
const loadLen=Number(${JSON.stringify(loadLen)});
const autoScrollBy = value => {
window.scrollBy({top: value});
document.querySelectorAll('html,body,div,p').forEach(d => {if(d)d.scrollTop += value});
};
const simulateClick = element => {
    try {
        const event = new MouseEvent('click', {
            bubbles: true,
            cancelable: true,
            composed: true,
        });
        element.dispatchEvent(event);
    } catch (error) {
        element.click();
    }
};
autoScrollBy(1500);
document.querySelectorAll('button').forEach(b => /加\s*载/.test(b.textContent) && simulateClick(b));
let c = document.body.cloneNode(true);

c.querySelectorAll(":not(p, br, p :not(a), :has(p, br))").forEach(el => {
 	for (let n of [...el.childNodes]) {
  if (n.nodeType == 3 && !(el.tagName == 'DIV' && /[一-龟]/.test(n.data))) n.remove();
}
});

let l = c.textContent.replace(/\s*\n\s*/g,'\n').length;

if(l>loadLen){
	return document.documentElement.outerHTML;
	}else{
		return null;
	}
})()`,true);
}catch(e){
	return result;
	}
}
function so(u1,u2){
let ur=/^https?:\/\/([^/:]+)/,
j1=u1.match(ur),j2=u2.match(ur);
return!/^javascript:/.test(u2)&&(!j2||j1[1]==j2[1]);
}
const htc = org.jsoup.Jsoup.parse(result);

for(let el of htc.select(":not(p, br, p :not(a), :has(p, br))")){
	if (el.tagName() == 'div' && /[一-龟]/.test(String(el.ownText()))) continue;
for (let n of [...el.childNodes()]) {
 if (n instanceof org.jsoup.nodes.TextNode) n.remove();
}
}

const rl= String(htc.body().wholeText()).replace(/\s*\n\s*/g,'\n').length;

const hs=[],
un=baseUrl.replace(/^https?:\/\/[^/]+\/|((_|(fenye|page)=)\d*)?[^\d]*$/g,''),
ht=org.jsoup.Jsoup.parse(rl<=loadLen?aWeb(baseUrl):result);

for(let aa of ht.select("a")){
	let hf=aa.attr('href');
if(hf&&hf!=baseUrl&&so(baseUrl,hf)){
	let tx=aa.text();
if(tx&&/下[—一]?页|^\s*Next/.test(tx)){java.put("下一页3",hf);
}else if(hf.includes(un)&&/(\d_|(fenye|page)=)\d/.test(hf)&&!/[?&]url=http/.test(hf)){hs.push(hf);}}}
java.put("下一页2",hs);
for(let el of ht.select(":not(p, br, p :not(a), :has(p, br))")){
		if (el.tagName() == 'div' && /[一-龟]/.test(String(el.ownText()))) continue;
for (let n of [...el.childNodes()]) {
 if (n instanceof org.jsoup.nodes.TextNode) n.remove();
}
}
ht.select("div,br,p").before("\n");
const bt=ht.body().wholeText();
java.put("文本",bt);
bt;
